   if(!o.hasData||!u.hasData||!p.hasData)return const LinearProgressIndicator();final orders=o.data!.docs,users=u.data!.docs,products=p.data!.docs;final sales=orders.where((d)=>_status(d.data())=='delivered').fold<double>(0,(v,d)=>v+_num(d.data()['total']));
