 Widget _marketing()=>_page('Marketing','Manage promo codes and homepage banners.',Column(children:[_panel('Promo codes',Column(children:[FilledButton(onPressed:()=>_simple('New promo code','Code',(v)=>FirebaseFirestore.instance.collection('promoCodes').doc(v.toUpperCase()).set({'active':true})),child:const Text('Add code')),_table('promoCodes',[_col('Code',(d)=>d.id),_col('Active',(d)=>(d.data()['active']??false).toString())],actions:(d)=>Switch(value:d.data()['active']==true,onChanged:(v)=>d.reference.update({'active':v}))) ])),const SizedBox(height:12),_panel('Homepage banners',Column(children:[FilledButton(onPressed:()=>_simple('New banner','Image URL',(v)=>FirebaseFirestore.instance.collection('banners').add({'image':v})),child:const Text('Add banner')),_table('banners',[_col('Image',(d)=>(d.data()['image']??'').toString())],actions:(d)=>IconButton(onPressed:()=>_delete(d.reference),icon:const Icon(Icons.delete))) ]))]));
 Widget _reports()=>_page('Reports','Live store performance summaries.',StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('orders').snapshots(),builder:(context,s){if(!s.hasData)return const CircularProgressIndicator();final docs=s.data!.docs,done=docs.where((d)=>_status(d.data())=='delivered');final sales=done.fold<double>(0,(v,d)=>v+_num(d.data()['total']));return Wrap(spacing:12,runSpacing:12,children:[_metric('Gross delivered sales','EGP '+sales.toStringAsFixed(2),Icons.payments,Color(0xff13b995)),_metric('Delivered orders',done.length.toString(),Icons.task_alt,_blue),_metric('All orders',docs.length.toString(),Icons.shopping_bag,Color(0xff8a50e8))]);}));
