 Widget _backup()=>_page('Backup & Restore','Export record counts. Use Firebase Console for full backups.',Wrap(children:[for(final c in ['products','orders','users','categories','promoCodes','banners'])Padding(padding:const EdgeInsets.all(5),child:OutlinedButton(onPressed:()=>_export(c),child:Text('Export '+c)))]));
 Widget _settings()=>_page('System Settings','Administrator and backend configuration.',_panel('Account & security',Column(children:[ListTile(title:Text(FirebaseAuth.instance.currentUser?.email??'Admin'),subtitle:const Text('Signed-in administrator')),const ListTile(title:Text('Access control'),subtitle:Text('users/{uid}.role == admin')),const ListTile(title:Text('Backend'),subtitle:Text('Firebase Authentication + Firestore')),FilledButton.tonal(onPressed:()=>FirebaseAuth.instance.signOut(),child:const Text('Sign out'))])));
 _Def _col(String t,String Function(QueryDocumentSnapshot<Map<String,dynamic>>) f)=>_Def(t,f);
 Widget _table(String collection,List<_Def> cols,{Widget Function(QueryDocumentSnapshot<Map<String,dynamic>>)? actions,int limit=250})=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection(collection).limit(limit).snapshots(),builder:(context,s){if(s.hasError)return Text('Firestore error: '+s.error.toString());if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Padding(padding:EdgeInsets.all(25),child:Text('No records found.')));return Card(clipBehavior:Clip.antiAlias,child:SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:[for(final c in cols)DataColumn(label:Text(c.title)),if(actions!=null)const DataColumn(label:Text('Actions'))],rows:[for(final d in s.data!.docs)DataRow(cells:[for(final c in cols)DataCell(ConstrainedBox(constraints:const BoxConstraints(maxWidth:220),child:Text(c.get(d),overflow:TextOverflow.ellipsis))),if(actions!=null)DataCell(actions(d))])])));});
 Future<void> _productDialog([QueryDocumentSnapshot<Map<String,dynamic>>? doc])async{final x=doc?.data()??{};final name=TextEditingController(text:(x['name']??'').toString()),price=TextEditingController(text:(x['price']??'').toString()),category=TextEditingController(text:(x['category']??'').toString()),qty=TextEditingController(text:(x['quantity']??'').toString()),image=TextEditingController(text:(x['image']??x['imageUrl']??'').toString()),desc=TextEditingController(text:(x['description']??'').toString());final form=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(doc==null?'Add product':'Edit product'),content:Form(key:form,child:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[_field(name,'Product name'),_field(price,'Price EGP',num:true),_field(category,'Category'),_field(qty,'Stock quantity',num:true),_field(image,'Image URL'),_field(desc,'Description')])))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:(){if(form.currentState!.validate())Navigator.pop(ctx,true);},child:const Text('Save'))]));if(ok==true){final data=<String,dynamic>{'name':name.text.trim(),'price':double.parse(price.text),'category':category.text.trim(),'quantity':int.tryParse(qty.text)??0,'image':image.text.trim(),'description':desc.text.trim(),'updatedAt':FieldValue.serverTimestamp()};if(doc==null)data['createdAt']=FieldValue.serverTimestamp();await(doc?.reference??FirebaseFirestore.instance.collection('products').doc()).set(data,SetOptions(merge:true));await _log('product_saved',name.text);}for(final c in [name,price,category,qty,image,desc]){c.dispose();}}
 Widget _field(TextEditingController c,String label,{bool num=false})=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextFormField(controller:c,keyboardType:num?TextInputType.number:TextInputType.text,validator:(v)=>v==null||v.trim().isEmpty?'Required':num&&double.tryParse(v)==null?'Enter a number':null,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
 Future<void> _stockDialog(QueryDocumentSnapshot<Map<String,dynamic>> d)async{final c=TextEditingController(text:(d.data()['quantity']??0).toString());final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Update stock'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))]));if(ok==true){final n=int.tryParse(c.text);if(n!=null&&n>=0){await d.reference.update({'quantity':n});await _log('stock_updated',d.id);}}c.dispose();}
 Future<void> _setStatus(QueryDocumentSnapshot<Map<String,dynamic>> d,String v)async{await d.reference.update({'status':v,'updatedAt':FieldValue.serverTimestamp()});await _log('order_status',d.id+' '+v);}
 Future<void> _delete(DocumentReference r)async{final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Delete record?'),content:const Text('This action cannot be undone.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Delete'))]));if(ok==true){await r.delete();await _log('record_deleted',r.id);}}
 Future<void> _simple(String title,String label,Future<void> Function(String) save)async{final c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:TextField(controller:c,decoration:InputDecoration(labelText:label)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))]));if(ok==true&&c.text.trim().isNotEmpty)await save(c.text.trim());c.dispose();}
 Future<void> _export(String c)async{final s=await FirebaseFirestore.instance.collection(c).get();if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Loaded '+s.docs.length.toString()+' '+c+' records. Use Firebase Console for a complete backup.')));}
 Future<void> _log(String a,String t)async{await FirebaseFirestore.instance.collection('adminActivity').add({'action':a,'target':t,'actorUid':FirebaseAuth.instance.currentUser?.uid,'actorEmail':FirebaseAuth.instance.currentUser?.email,'createdAt':FieldValue.serverTimestamp()});}
}
class _Def{final String title;final String Function(QueryDocumentSnapshot<Map<String,dynamic>>) get;_Def(this.title,this.get);}
class _NotifyForm extends StatefulWidget{final Future<void> Function(String,String) send;const _NotifyForm({required this.send});@override State<_NotifyForm> createState()=>_NotifyFormState();}
class _NotifyFormState extends State<_NotifyForm>{final t=TextEditingController(),b=TextEditingController();bool busy=false;@override void dispose(){t.dispose();b.dispose();super.dispose();}@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(15),child:Column(children:[TextField(controller:t,decoration:const InputDecoration(labelText:'Title')),TextField(controller:b,maxLines:3,decoration:const InputDecoration(labelText:'Message')),Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:busy?null:()async{if(t.text.trim().isEmpty||b.text.trim().isEmpty)return;setState(()=>busy=true);try{await widget.send(t.text.trim(),b.text.trim());t.clear();b.clear();}finally{if(mounted)setState(()=>busy=false);}},icon:const Icon(Icons.send),label:Text(busy?'Sending':'Send notification')))])));}
String _status(Map<String,dynamic> d)=>(d['status']??'pending').toString().toLowerCase();
double _num(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;
